import{_ as t,o as a,c as d,a2 as i}from"./chunks/framework.CRfKVJQk.js";const u=JSON.parse('{"title":"Property behaviour and precedence","description":"How Liquid Glass props combine: material defaults, theme overrides, explicit props, intensity, clamping, platform behaviour, fallbacks and animation.","frontmatter":{"description":"How Liquid Glass props combine: material defaults, theme overrides, explicit props, intensity, clamping, platform behaviour, fallbacks and animation.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-glass-effect/features/precedence"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-glass-effect/features/precedence"}],["meta",{"property":"og:title","content":"Property behaviour and precedence · Liquid Glass for React Native"}],["meta",{"property":"og:description","content":"How Liquid Glass props combine: material defaults, theme overrides, explicit props, intensity, clamping, platform behaviour, fallbacks and animation."}],["meta",{"name":"twitter:title","content":"Property behaviour and precedence · Liquid Glass for React Native"}],["meta",{"name":"twitter:description","content":"How Liquid Glass props combine: material defaults, theme overrides, explicit props, intensity, clamping, platform behaviour, fallbacks and animation."}]]},"headers":[],"relativePath":"features/precedence.md","filePath":"features/precedence.md"}'),o={name:"features/precedence.md"};function r(s,e,n,c,l,h){return a(),d("div",null,[...e[0]||(e[0]=[i(`<h1 id="property-behaviour-and-precedence" tabindex="-1">Property behaviour and precedence <a class="header-anchor" href="#property-behaviour-and-precedence" aria-label="Permalink to &quot;Property behaviour and precedence&quot;">​</a></h1><p>How the library turns a material, a theme and your props into what&#39;s drawn. Everything on this page comes from <code>src/materials/resolveMaterial.ts</code> and <code>src/components/LiquidGlassView/useResolvedGlass.ts</code>.</p><h2 id="order-of-precedence" tabindex="-1">Order of precedence <a class="header-anchor" href="#order-of-precedence" aria-label="Permalink to &quot;Order of precedence&quot;">​</a></h2><p>For each look value, the last source that sets it wins:</p><ol><li><strong>The built-in material preset</strong> (<code>material</code>, or the theme&#39;s <code>defaultMaterial</code>, or <code>regular</code>).</li><li><strong>The theme&#39;s override</strong> for that material (<code>GlassThemeProvider</code> → <code>materials</code>).</li><li><strong>The component prop</strong> (<code>blur</code>, <code>tint</code>, <code>refraction</code>…).</li><li>Then <strong><code>intensity</code></strong> scales the effect strengths, and every value is <strong>clamped</strong> to a safe range.</li></ol><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">GlassThemeProvider</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> theme</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ materials: { thick: { blur: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } } }}&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">LiquidGlassView</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> material</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;thick&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;            {</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* blur 40: theme beats preset (36) */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">LiquidGlassView</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> material</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;thick&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> blur</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} /&gt;  {</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* blur 12: prop beats theme */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">GlassThemeProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Changing <code>material</code> while other props are set keeps your props: only the values you didn&#39;t set come from the new material.</p><h2 id="what-intensity-does" tabindex="-1">What <code>intensity</code> does <a class="header-anchor" href="#what-intensity-does" aria-label="Permalink to &quot;What \`intensity\` does&quot;">​</a></h2><p><code>intensity</code> (0–1, default 1) multiplies these values after they&#39;re resolved:</p><table tabindex="0"><thead><tr><th>Scaled by <code>intensity</code></th><th>Not scaled</th></tr></thead><tbody><tr><td><code>blur</code>, <code>refraction</code>, <code>distortion</code>, <code>illumination</code>, <code>chromaticAberration</code></td><td><code>tint</code>, <code>tintOpacity</code>, <code>edgeWidth</code>, <code>borderWidth</code>, <code>borderOpacity</code>, <code>lightAngle</code>, <code>cornerRadius</code></td></tr></tbody></table><p>So <code>intensity={0}</code> gives a tinted, bordered surface with no blur, lensing or rim light. It doesn&#39;t make the view invisible.</p><h2 id="ranges-and-invalid-values" tabindex="-1">Ranges and invalid values <a class="header-anchor" href="#ranges-and-invalid-values" aria-label="Permalink to &quot;Ranges and invalid values&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Range</th><th>Out of range or invalid</th></tr></thead><tbody><tr><td><code>blur</code></td><td>0–100 dp</td><td>Clamped</td></tr><tr><td><code>intensity</code>, <code>tintOpacity</code>, <code>refraction</code>, <code>distortion</code>, <code>illumination</code>, <code>chromaticAberration</code>, <code>borderOpacity</code></td><td>0–1</td><td>Clamped</td></tr><tr><td><code>edgeWidth</code></td><td>0–64 dp</td><td>Clamped</td></tr><tr><td><code>borderWidth</code></td><td>0–8 dp</td><td>Clamped</td></tr><tr><td><code>lightAngle</code></td><td>any number</td><td>Wrapped into −180…180. A non-finite value becomes −60</td></tr><tr><td><code>transitionDuration</code></td><td>0–2000 ms</td><td>Clamped</td></tr><tr><td><code>cornerRadius</code></td><td>≥ 0</td><td>Negative becomes 0. Clamped natively to half the shortest side</td></tr><tr><td><code>material</code></td><td>the six names</td><td>Unknown name: a one-time dev warning, then the default material</td></tr><tr><td><code>quality</code></td><td><code>auto</code> <code>high</code> <code>medium</code> <code>low</code> <code>static</code></td><td>Unknown value: a one-time dev warning, then the theme default</td></tr></tbody></table><h2 id="where-each-value-comes-from-when-you-don-t-set-it" tabindex="-1">Where each value comes from when you don&#39;t set it <a class="header-anchor" href="#where-each-value-comes-from-when-you-don-t-set-it" aria-label="Permalink to &quot;Where each value comes from when you don&#39;t set it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th></tr></thead><tbody><tr><td><code>material</code></td><td>theme <code>defaultMaterial</code> (<code>regular</code>)</td></tr><tr><td><code>cornerRadius</code></td><td><code>style.borderRadius</code> if it&#39;s a number, else theme <code>cornerRadius</code> (24). Percentage strings are ignored</td></tr><tr><td><code>quality</code></td><td>theme <code>defaultQuality</code> (<code>auto</code>)</td></tr><tr><td><code>iosRenderer</code></td><td>theme <code>iosRenderer</code> (<code>system</code>)</td></tr><tr><td><code>reduceTransparency</code></td><td><code>&#39;auto&#39;</code>: follows iOS Reduce Transparency (always off on Android and web)</td></tr><tr><td><code>interactive</code></td><td><code>false</code> (<code>true</code> on <code>LiquidGlassButton</code>)</td></tr><tr><td><code>motionLighting</code></td><td><code>false</code></td></tr><tr><td><code>transitionDuration</code></td><td>180 ms</td></tr><tr><td><code>clipContent</code></td><td><code>true</code></td></tr><tr><td><code>lightAngle</code></td><td>−60</td></tr></tbody></table><h2 id="quality" tabindex="-1">Quality <a class="header-anchor" href="#quality" aria-label="Permalink to &quot;Quality&quot;">​</a></h2><p><code>quality</code> doesn&#39;t change the resolved look values. It tells the native renderer how much work to do: whether to run the refraction shader, how often to re-capture on Android 7–11, and whether to capture only once (<code>static</code>). <code>auto</code> is decided natively per device. See <a href="/react-native-glass-effect/features/quality">Quality and performance</a>.</p><h2 id="when-a-platform-can-t-draw-an-effect" tabindex="-1">When a platform can&#39;t draw an effect <a class="header-anchor" href="#when-a-platform-can-t-draw-an-effect" aria-label="Permalink to &quot;When a platform can&#39;t draw an effect&quot;">​</a></h2><p>The prop is accepted and ignored: no error, and no warning. For example <code>refraction</code> on Android 12 or on the web. The <a href="/react-native-glass-effect/components/liquid-glass-view#platform-behaviour">platform tables</a> list what each platform draws.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The library doesn&#39;t warn in development when you set a prop the current platform ignores. That would be a useful addition; see <a href="https://github.com/SachinMeenaSipl/react-native-glass-effect/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">Contributing</a>.</p></div><h2 id="fallbacks" tabindex="-1">Fallbacks <a class="header-anchor" href="#fallbacks" aria-label="Permalink to &quot;Fallbacks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What&#39;s drawn</th></tr></thead><tbody><tr><td><code>reduceTransparency</code> resolves to on</td><td>An opaque surface in <code>fallbackColor</code></td></tr><tr><td>Android: no backdrop behind the glass, or the glass is inside one</td><td>The opaque fallback surface, and one log line</td></tr><tr><td>Android: the GPU rejects the shader</td><td>The <code>blur</code> renderer (no refraction)</td></tr><tr><td>Expo Go, tests, missing native code</td><td>A tinted view: the tint at least 55% opaque, the border and corner radius, no blur</td></tr><tr><td>Web</td><td>The CSS renderer: <code>backdrop-filter: blur(&lt;blur&gt;px) saturate(160%)</code>, the tint at <code>tintOpacity</code>, border and corners</td></tr></tbody></table><h2 id="animation" tabindex="-1">Animation <a class="header-anchor" href="#animation" aria-label="Permalink to &quot;Animation&quot;">​</a></h2><p>When glass props change, the new values animate over <code>transitionDuration</code> ms. On Android the change is interpolated in native code (<code>GlassConfigTransition</code>), so React renders once and the frames are drawn natively. On iOS the system effect animates. On the web, changes apply immediately.</p><p>With Reduce Motion on, prop changes apply without animation.</p>`,25)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
